// Constructed scenario — week3 diagnosis
// HTML:   <div id="result">Empty</div>
//         <button hx-get="/fragment" hx-target="#result" hx-swap="none">Load</button>
// Server: GET /fragment → 200 text/html "Loaded"
// Action: click Load
// Expected (as reported): #result contains "Loaded"
// Actual:                  #result remains "Empty"

describe('week3: hx-swap="none" with hx-target — failing reproduction', function() {
  beforeEach(function() {
    this.server = makeServer()
    clearWorkArea()
  })
  afterEach(function() {
    this.server.restore()
    clearWorkArea()
  })

  // FAILING: asserts the user's expectation — this must fail to prove the reproduction
  it('REPRO: #result shows "Loaded" after click (expects swap despite hx-swap="none")', function() {
    this.server.respondWith('GET', '/fragment', [200, { 'Content-Type': 'text/html' }, 'Loaded'])
    var result = make('<div id="result">Empty</div>')
    var button  = make('<button hx-get="/fragment" hx-target="#result" hx-swap="none">Load</button>')
    button.click()
    this.server.respond()
    this.server.requests.length.should.equal(1)
    // This assertion is expected to FAIL: hx-swap="none" tells htmx to make no swap
    result.textContent.should.equal('Loaded')
  })
})

// Constructed scenario — week3 diagnosis (CORRECTED)
// Root cause: hx-swap="none" suppresses all DOM swaps by design.
// Fix applied: remove hx-swap="none" so the default swap (innerHTML) takes effect.
//
// Original (broken):
//   <button hx-get="/fragment" hx-target="#result" hx-swap="none">Load</button>
// Corrected:
//   <button hx-get="/fragment" hx-target="#result">Load</button>
//             (default hx-swap is "innerHTML")

describe('week3: hx-swap="none" with hx-target — corrected', function() {
  beforeEach(function() {
    this.server = makeServer()
    clearWorkArea()
  })
  afterEach(function() {
    this.server.restore()
    clearWorkArea()
  })

  it('corrected: #result shows "Loaded" after click (hx-swap="none" removed, default innerHTML used)', function() {
    this.server.respondWith('GET', '/fragment', [200, { 'Content-Type': 'text/html' }, 'Loaded'])
    var result = make('<div id="result">Empty</div>')
    var button  = make('<button hx-get="/fragment" hx-target="#result">Load</button>')
    button.click()
    this.server.respond()
    this.server.requests.length.should.equal(1)
    result.textContent.should.equal('Loaded')
  })

  it('confirmed: hx-swap="none" explicitly suppresses swap regardless of target or response', function() {
    this.server.respondWith('GET', '/fragment', [200, { 'Content-Type': 'text/html' }, 'Loaded'])
    var result = make('<div id="result">Empty</div>')
    var button  = make('<button hx-get="/fragment" hx-target="#result" hx-swap="none">Load</button>')
    button.click()
    this.server.respond()
    this.server.requests.length.should.equal(1)
    // Request fires; response arrives; DOM is intentionally untouched
    result.textContent.should.equal('Empty')
  })
})
